const icons={close:'<path d="m6 6 12 12M6 18 18 6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>'};const ic=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]}</svg>`;
const API=['localhost','127.0.0.1'].includes(location.hostname)&&location.port==='8787'?location.origin:'https://coursecue.hrk-6888.workers.dev';
let courses=['人材マネジメントⅡ','コーポレートファイナンスⅡ','国際ビジネス戦略','サービス・マーケティング','意思決定論','管理会計Ⅱ','マーケティング戦略','ボランティア','経営科学Ⅱ','経済言論Ⅱ','言葉と文化'];
const courseIds=['103578','103901','103576','103573','103889','103904','103572','103736','103887','103914','104493'];
const statuses={ready:['未着手','ready'],answered:['本人の提出待ち','wait'],wait:['要確認','wait'],code:['出席コード待ち','wait'],draft:['下書き','draft'],done:['提出済み','done'],unknown:['提出結果不明','wait']};const taskTypes=['課題','レポート','クイズ'];
const views={home:'ホーム',courses:'授業',tasks:'課題',needs:'要対応',settings:'設定'};
const emptyState=()=>({tasks:[],materials:[],settings:{time:'16:30'}});
let state=emptyState(),view='home',filter='all',query='',selectedCourse=null,lastFocus=null,dialogDone=null,key=localStorage.getItem('coursecue-owner')||'';
const ownerCourses=[...courses];let guestData;try{guestData=JSON.parse(localStorage.getItem('coursecue-personal')||'null')}catch{}if(!key){courses=guestData?.courses||[];state=guestData?.state||emptyState();}function savePersonal(){localStorage.setItem('coursecue-personal',JSON.stringify({courses,state}));}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const DAY=86400000,HOUR=3600000;const dueTime=t=>t.dueAt?new Date(t.dueAt).getTime():null;
const when=s=>s?new Date(s).toLocaleString('ja-JP',{timeZone:'Asia/Tokyo',month:'numeric',day:'numeric',weekday:'short',hour:'2-digit',minute:'2-digit'}):'未確認';
const needs=t=>['wait','code','unknown','answered'].includes(t.status);const pending=t=>t.status!=='done';
const overdue=t=>pending(t)&&!!t.dueAt&&dueTime(t)<=Date.now();const soon=t=>pending(t)&&!!t.dueAt&&dueTime(t)>Date.now()&&dueTime(t)-Date.now()<=3*DAY;
function remaining(t){const ms=dueTime(t)-Date.now(),a=Math.abs(ms),span=a>=DAY?Math.floor(a/DAY)+'日':a>=HOUR?Math.floor(a/HOUR)+'時間':Math.max(1,Math.floor(a/60000))+'分';return ms<=0?'期限切れ · '+span+'超過':'あと'+span}
function deadline(t){if(!t.dueAt)return '<span class="deadline">締切未確認</span>';if(!pending(t))return `<span class="deadline">締切 ${when(t.dueAt)}</span>`;const level=overdue(t)?'overdue':dueTime(t)-Date.now()<=DAY?'urgent':soon(t)?'soon':'';return `<span class="deadline ${level}">締切 ${when(t.dueAt)}<small>${remaining(t)}</small></span>`}
const localInput=s=>{if(!s)return '';const d=new Date(s);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,16)};
const round=t=>t.round?'第'+t.round+'回':'回数未確認';
async function api(path,method='GET',data){const r=await fetch(API+path,{method,headers:{Authorization:'Bearer '+key,'Content-Type':'application/json'},body:data?JSON.stringify(data):undefined});if(r.status===401)throw Error('Macから接続してください');if(!r.ok)throw Error('接続できません');return r.json()}
function toast(s){const e=document.getElementById('toast');e.textContent=s;e.style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>e.style.display='none',5000)}
async function load(){if(document.activeElement?.matches('input,textarea,select'))return;if(!key){render();return}try{state=await api('/api/state');render()}catch(e){toast(e.message);render()}}
async function job(kind,task=null,payload={}){if(!key){toast('manabo連携が必要です');return}try{const queued=await api('/api/jobs','POST',{kind,task,payload});toast(kind==='sync'?'同期を開始します':kind==='generate'?'自動回答を開始します':kind==='supplement'?'保存しました':'処理を予約しました');if(['generate','sync'].includes(kind)){const buttonId=kind==='sync'?'sync':'generate';const button=document.getElementById(buttonId);if(button){button.disabled=true;button.textContent=kind==='sync'?'同期開始待ち…':'開始待ち…';}const poll=setInterval(async()=>{try{const jobs=await api('/api/jobs');const current=jobs.find(j=>j.id===queued.id);if(!current)return;const button=document.getElementById(buttonId);if(button){button.disabled=true;button.textContent=current.status==='running'?(kind==='sync'?'同期中…':'回答中…'):'開始待ち…';}if(['done','waiting','failed'].includes(current.status)){clearInterval(poll);await load();if(task&&document.getElementById('overlay').classList.contains('open'))detail(task);const result=typeof current.result==='string'?JSON.parse(current.result):current.result;toast(kind==='sync'&&current.status==='done'?'同期しました':result?.message||'処理を確認してください');}}catch{clearInterval(poll);toast('処理状況を取得できません');}},2000);}await load()}catch(e){toast(e.message)}}
// confirm() の代わりに使う確認ダイアログ
function ask(message,ok='OK',danger=false){return new Promise(resolve=>{const d=document.getElementById('dialog'),prev=document.activeElement;d.innerHTML=`<div class="modal" role="alertdialog" aria-modal="true" aria-labelledby="dialog-title" aria-describedby="dialog-text"><div class="modal-header" id="dialog-title">確認</div><p class="modal-body" id="dialog-text">${esc(message)}</p><div class="modal-footer"><button class="btn" id="dialog-cancel">キャンセル</button><button class="btn ${danger?'btn-danger':'btn-primary'}" id="dialog-ok">${esc(ok)}</button></div></div>`;d.classList.add('open');const done=v=>{d.classList.remove('open');d.innerHTML='';dialogDone=null;prev?.focus?.();resolve(v)};dialogDone=done;document.getElementById('dialog-ok').onclick=()=>done(true);document.getElementById('dialog-cancel').onclick=()=>done(false);d.onclick=e=>{if(e.target===d)done(false)};document.getElementById('dialog-cancel').focus()})}
function openDrawer(title,body,focusId){lastFocus=document.activeElement;document.getElementById('drawer').innerHTML=`<div class="drawerhead"><h2 id="drawer-title">${esc(title)}</h2><button class="close" id="close" aria-label="閉じる">${ic('close')}</button></div><div class="drawerbody">${body}</div>`;document.getElementById('overlay').classList.add('open');document.body.style.overflow='hidden';document.getElementById('close').onclick=close;document.getElementById(focusId||'close').focus()}
function close(){const o=document.getElementById('overlay');if(!o.classList.contains('open'))return;o.classList.remove('open');document.body.style.overflow='';lastFocus?.focus?.()}
const panel=(title,body,{mark=true,center=false,tools='',flush=false}={})=>`<section class="panel"><h2 class="panel-heading${center?' center':''}">${mark?'<span class="mark" aria-hidden="true"></span>':''}${title}${tools?`<span class="tools">${tools}</span>`:''}</h2><div class="panel-body${flush?' flush':''}">${body}</div></section>`;
function row(t){const [label,cl]=statuses[t.status]||['未確認','ready'];return `<li><button class="task" data-task="${esc(t.id)}"><span class="task-main"><span class="task-title">${esc(t.title)}</span><span class="meta">${esc(courses[t.course]??'授業未設定')} · ${round(t)} · ${esc(t.type||'課題')}</span>${needs(t)&&t.action?`<span class="rowaction">${esc(t.action)}</span>`:''}</span><span class="right"><span class="label ${cl}">${label}</span>${deadline(t)}</span></button></li>`}
function matched(t){const q=query.trim().toLowerCase();return(!q||((courses[t.course]||'')+t.title).toLowerCase().includes(q))&&(selectedCourse===null||selectedCourse===t.course)&&(filter==='all'||filter==='pending'&&pending(t)||filter==='done'&&!pending(t)||filter==='soon'&&soon(t)||filter==='overdue'&&overdue(t))}
const byDue=(a,b)=>(pending(b)-pending(a))||((dueTime(a)??Infinity)-(dueTime(b)??Infinity));
function list(rows,tabs=true,empty='課題はありません'){const shown=rows.filter(matched).sort(byDue);return `${tabs?`<div class="tabs">${[['all','すべて'],['pending','未提出'],['overdue','期限切れ'],['soon','3日以内'],['done','提出済み']].map(([v,l])=>`<button class="tab ${v===filter?'active':''}" data-filter="${v}" aria-pressed="${v===filter}">${l}</button>`).join('')}</div>`:''}${shown.length?`<ul class="tasklist">${shown.map(row).join('')}</ul>`:`<p class="empty">${query?'検索に一致する課題はありません':empty}</p>`}`}
function directory(){return panel('ディレクトリ',`<button class="topdir ${view==='courses'&&selectedCourse===null?'selected':''}" data-view="courses">授業一覧</button><ul class="dirlist">${courses.map((c,i)=>{const n=state.tasks.filter(t=>t.course===i&&pending(t)).length;return `<li><button data-course="${i}" class="${selectedCourse===i?'selected':''}"${selectedCourse===i?' aria-current="page"':''}><img class="folder-icon" src="/folder-icon.png" alt="" width="16" height="12">${esc(c)}${n?`<span class="badge">${n}<span class="sr-only">件未提出</span></span>`:''}</button></li>`}).join('')}</ul>`,{mark:false,center:true})}
function courseTable(){const rows=courses.map((c,i)=>({c,i})).filter(({c})=>!query||c.toLowerCase().includes(query.trim().toLowerCase()));return rows.length?`<table class="table-default"><thead><tr><th scope="col">授業名</th><th scope="col" class="num">課題</th><th scope="col" class="num">未提出</th></tr></thead><tbody>${rows.map(({c,i})=>{const ts=state.tasks.filter(t=>t.course===i);return `<tr><td><button class="linklike" data-course="${i}">${esc(c)}</button></td><td class="num">${ts.length}</td><td class="num">${ts.filter(pending).length}</td></tr>`}).join('')}</tbody></table>`:'<p class="empty">授業がありません</p>'}
const addCourseForm=()=>`<div class="field"><label for="newcourse">授業名</label><div class="inline"><input class="form-control" id="newcourse" placeholder="例：経済原論Ⅱ"><button class="btn btn-primary" id="addcourse">追加</button></div></div>`;
function render(){const n=state.tasks.filter(needs).length;
document.getElementById('gnav').innerHTML=`<ul>${Object.entries(views).map(([v,l])=>`<li><button data-view="${v}" class="${view===v?'active':''}"${view===v?' aria-current="page"':''}>${l}${v==='needs'&&n?`<span class="badge">${n}<span class="sr-only">件</span></span>`:''}</button></li>`).join('')}</ul>`;
document.getElementById('headeraction').innerHTML=key?'<button class="btn btn-black" id="sync">同期</button>':courses.length?'<button class="btn btn-black" id="addtask">課題を追加</button>':'';
document.getElementById('mode').textContent=key?'manabo連携':'個人用';
const macOnline=state.deviceSeen&&Date.now()-new Date(state.deviceSeen)<60000;document.getElementById('status').innerHTML=(key?[`自動確認 ${state.settings?.time||'16:30'}`,macOnline?'Mac 接続中':'Mac 未接続',state.running?'処理中':state.lastSync?'同期 '+when(state.lastSync):'同期待ち']:['このブラウザに保存']).map(s=>`<li>${esc(s)}</li>`).join('');
const title=view==='courses'&&selectedCourse!==null?courses[selectedCourse]:views[view];const trail=[['home','ホーム']];if(view!=='home')trail.push([view,views[view]]);if(view==='courses'&&selectedCourse!==null)trail.push(['',courses[selectedCourse]]);document.getElementById('breadcrumb').innerHTML=trail.map(([v,l],i)=>i===trail.length-1?`<li class="active" aria-current="page">${esc(l)}</li>`:`<li><button class="linklike" data-view="${v}">${esc(l)}</button></li>`).join('');document.getElementById('pagetitle').textContent=title;document.title=`${title} — saboro`;
let html='';
if(view==='home'){const stats=[['pending','未提出',state.tasks.filter(pending).length],['needs','要対応',n],['overdue','期限切れ',state.tasks.filter(overdue).length],['soon','3日以内',state.tasks.filter(soon).length],['done','提出済み',state.tasks.filter(t=>!pending(t)).length]];if(state.lastError)html+=`<div class="alert alert-warning">${esc(state.lastError)} <a href="http://127.0.0.1:8766/setup" target="_blank" rel="noopener">Mac設定を開く</a></div>`;html+=panel('概要',`<div class="stats">${stats.map(([v,l,c])=>`<button class="stat ${['needs','overdue'].includes(v)&&c?'alert-'+v:''}" data-stat="${v}"><span class="stat-label">${l}</span><span class="stat-num">${c}<small>件</small></span></button>`).join('')}</div>`);if(n)html+=panel('要対応',list(state.tasks.filter(needs),false),{flush:true});html+=panel('未提出の課題',list(state.tasks.filter(t=>pending(t)&&!needs(t)),false,'未提出の課題はありません'),{flush:true,tools:'締切順'})}
else if(view==='courses'){if(selectedCourse===null)html+=panel('授業一覧',courseTable());else{html+=panel(`${esc(courses[selectedCourse])} - 課題一覧`,list(state.tasks),{flush:true});const mats=state.materials.filter(m=>m.course===courses[selectedCourse]);if(key)html+=panel(`${esc(courses[selectedCourse])} - 資料`,mats.length?`<div class="materials">${mats.map(m=>`<a class="btn btn-sm" href="${esc(m.url)}" target="_blank" rel="noopener">${esc(m.name)}</a>`).join('')}</div>`:'<p class="empty">資料はまだ取得されていません</p>')}}
else if(view==='tasks')html+=panel('課題一覧',list(state.tasks),{flush:true});
else if(view==='needs')html+=panel('要対応',list(state.tasks.filter(needs),false,'対応が必要な課題はありません'),{flush:true});
else if(!key){html+=panel('授業',`${courses.length?courses.map((c,i)=>`<div class="course-edit"><input class="form-control" id="coursename-${i}" value="${esc(c)}" aria-label="授業名（${esc(c)}）"><button class="btn btn-sm" data-rename="${i}">名前を保存</button><button class="btn btn-sm" data-delcourse="${i}">削除</button></div>`).join(''):''}<div class="actions" style="display:block">${addCourseForm()}</div>`);html+=panel('データ',`<p>データはこのブラウザだけに保存されます。別の端末で使うときや、ブラウザのデータを消す前にバックアップしてください。</p><div class="actions"><button class="btn" id="exportpersonal">バックアップを保存</button><input class="file-input" id="importpersonal" type="file" accept="application/json"><label class="btn" for="importpersonal">バックアップを読み込む</label></div>`);html+=panel('manabo連携',`<details><summary>自動連携について</summary><p>現在の自動連携は、登録済みMacを使用します。</p><a class="btn" href="http://127.0.0.1:8766/setup" target="_blank" rel="noopener">Macを接続</a></details>`)}
else{html+=panel('manabo連携',`<table class="table-default"><tr><th>認証情報</th><td>${state.credentialsConfigured?'キーチェーン保存済み':'未設定'}</td></tr></table><div class="field" style="margin-top:15px"><label for="manabo-id">manabo ID</label><input class="form-control" id="manabo-id" autocomplete="username"></div><div class="field"><label for="manabo-password">パスワード</label><input class="form-control" id="manabo-password" type="password" autocomplete="current-password"><small>暗号化してMacのキーチェーンに保存します。</small></div><div class="actions"><button class="btn btn-primary" id="savecredentials">保存</button><button class="btn" id="verifylogin">接続確認</button></div>`);html+=panel('自動処理',`<div class="field"><label for="time">実行時刻（日本時間）</label><input class="form-control" style="max-width:160px" type="time" id="time" value="${esc(state.settings?.time||'16:30')}"></div><label class="check"><input type="checkbox" id="autogen" ${state.settings?.autoGenerate!==false?'checked':''}> 自動課題生成</label><p>クイズ：自動回答後、本人がmanaboで提出</p><p class="muted">出席コードあり：問題のみ回答・提出待ち</p><button class="btn btn-primary" id="savesettings">保存</button>`);html+=panel('授業日',`<p class="muted">初回日から週ごとの日程を設定します。休講・変更日は個別に設定してください。</p>${courses.map((c,i)=>`<div class="field"><label for="schedule-${i}">${esc(c)} · 第1回</label><input class="form-control" style="max-width:200px" type="date" id="schedule-${i}" data-schedule="${i}" value="${esc(state.schedules?.[courseIds[i]]?.[1]||'')}"></div>`).join('')}<button class="btn" id="saveschedule">日程を保存</button>`);html+=`<button class="btn" id="logout">この端末の接続を解除</button>`}
if(!key&&!courses.length&&view!=='settings')html=`<div class="col-full">${panel('授業を追加',`<p>はじめに授業を登録してください。登録した授業ごとに課題と締切を管理できます。</p>${addCourseForm()}`)}</div>`;else html=`<div class="col-side">${directory()}</div><div class="col-main">${html}</div>`;
document.getElementById('app').innerHTML=html;bindView()}
function bindView(){const bind=(id,f)=>{const e=document.getElementById(id);if(e)e.onclick=f};
bind('addcourse',()=>{const name=document.getElementById('newcourse').value.trim();if(!name){toast('授業名を入力してください');return}if(courses.includes(name)){toast('登録済みの授業です');return}courses.push(name);savePersonal();if(view!=='settings')view='home';render();toast('授業を追加しました')});
bind('addtask',()=>{if(!courses.length){view='settings';render();return}openDrawer('課題を追加',`<div class="field"><label for="tasktitle">課題名</label><input class="form-control" id="tasktitle"></div><div class="field"><label for="taskcourse">授業</label><select class="form-control" id="taskcourse">${courses.map((c,i)=>`<option value="${i}"${selectedCourse===i?' selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="field"><label for="tasktype">種類</label><select class="form-control" id="tasktype">${taskTypes.map(v=>`<option>${v}</option>`).join('')}</select></div><div class="field"><label for="taskdue">締切</label><input class="form-control" id="taskdue" type="datetime-local"></div><div class="actions"><button class="btn btn-primary" id="createtask">追加</button><button class="btn" id="cancelcreate">キャンセル</button></div>`,'tasktitle');document.getElementById('cancelcreate').onclick=close;document.getElementById('createtask').onclick=()=>{const title=document.getElementById('tasktitle').value.trim(),due=document.getElementById('taskdue').value;if(!title){toast('課題名を入力してください');return}state.tasks.push({id:crypto.randomUUID(),title,course:+document.getElementById('taskcourse').value,dueAt:due?new Date(due).toISOString():null,status:'ready',type:document.getElementById('tasktype').value||'課題',answer:'',description:'',url:''});savePersonal();close();render();toast('課題を追加しました')}});
bind('exportpersonal',()=>{const a=document.createElement('a'),u=URL.createObjectURL(new Blob([JSON.stringify({version:1,courses,state})],{type:'application/json'}));a.href=u;a.download='saboro-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)});
const importer=document.getElementById('importpersonal');if(importer)importer.onchange=async()=>{try{const d=JSON.parse(await importer.files[0].text());if(d.version!==1||!Array.isArray(d.courses)||!d.courses.every(c=>typeof c==='string')||!Array.isArray(d.state?.tasks)||!Array.isArray(d.state?.materials)||d.state.tasks.some(t=>typeof t.id!=='string'||typeof t.title!=='string'||!Number.isInteger(t.course)||t.course<0||t.course>=d.courses.length))throw Error();if(!await ask('このブラウザのデータをバックアップの内容で置き換えますか？現在のデータは消えます。','置き換える',true))return;courses=d.courses;state=d.state;selectedCourse=null;savePersonal();render();toast('読み込みました')}catch{toast('バックアップを確認してください')}finally{importer.value=''}};
document.querySelectorAll('[data-rename]').forEach(e=>e.onclick=()=>{const i=+e.dataset.rename,name=document.getElementById('coursename-'+i).value.trim();if(!name){toast('授業名を入力してください');return}if(courses.some((c,j)=>c===name&&j!==i)){toast('登録済みの授業です');return}courses[i]=name;savePersonal();render();toast('授業名を変更しました')});
document.querySelectorAll('[data-delcourse]').forEach(e=>e.onclick=async()=>{const i=+e.dataset.delcourse,count=state.tasks.filter(t=>t.course===i).length;if(!await ask(`「${courses[i]}」${count?`と課題${count}件`:''}を削除しますか？元に戻せません。`,'削除',true))return;state.tasks=state.tasks.filter(t=>t.course!==i).map(t=>t.course>i?{...t,course:t.course-1}:t);courses.splice(i,1);selectedCourse=null;savePersonal();render();toast('授業を削除しました')});
bind('sync',()=>job('sync'));bind('verifylogin',()=>job('verify'));
bind('savecredentials',async()=>{const username=document.getElementById('manabo-id').value.trim(),password=document.getElementById('manabo-password').value;if(!username||!password){toast('ID・パスワードを入力してください');return}if(!state.credentialPublicKey){toast('Macの接続を確認してください');return}try{const {encryptCredentials}=await import('./credentials.js');const payload=await encryptCredentials(state.credentialPublicKey,username,password);await api('/api/jobs','POST',{kind:'credentials',payload});document.getElementById('manabo-password').value='';toast('保存を予約しました。Macで処理します。')}catch{toast('保存できませんでした')}});
bind('logout',async()=>{if(!await ask('この端末とMacの接続を解除しますか？再接続にはMacの設定画面が必要です。','解除する',true))return;key='';localStorage.removeItem('coursecue-owner');courses=guestData?.courses||[];state=guestData?.state||emptyState();view='home';selectedCourse=null;render()});
bind('savesettings',()=>job('settings',null,{time:document.getElementById('time').value,autoGenerate:document.getElementById('autogen').checked,autoSubmitQuiz:false}));
bind('saveschedule',()=>{const schedules={...state.schedules};document.querySelectorAll('[data-schedule]').forEach(e=>{if(!e.value)return;const dates={};for(let n=1;n<=15;n++){const d=new Date(e.value+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+7*(n-1));dates[n]=d.toISOString().slice(0,10)}schedules[courseIds[+e.dataset.schedule]]=dates});job('settings',null,{schedules})});
document.querySelectorAll('[data-stat]').forEach(e=>e.onclick=()=>{view=e.dataset.stat==='needs'?'needs':'tasks';filter=e.dataset.stat==='needs'?'all':e.dataset.stat;selectedCourse=null;render()});
document.querySelectorAll('[data-filter]').forEach(e=>e.onclick=()=>{filter=e.dataset.filter;render()});
document.querySelectorAll('[data-view]').forEach(e=>e.onclick=()=>{view=e.dataset.view;selectedCourse=null;filter='all';render();scrollTo(0,0)});
document.querySelectorAll('[data-course]').forEach(e=>e.onclick=()=>{view='courses';selectedCourse=+e.dataset.course;filter='all';render()});
document.querySelectorAll('[data-task]').forEach(e=>e.onclick=()=>detail(e.dataset.task))}
function detail(id){const t=state.tasks.find(t=>t.id===id);if(!t)return;const [label,cl]=statuses[t.status]||['未確認','ready'];const quiz=t.type==='クイズ';
let body=`<p class="drawer-label">${esc(courses[t.course]??'授業未設定')} · ${round(t)} · ${esc(t.type||'課題')}</p><span class="label ${cl}">${label}</span><table class="table-default"><tr><th>締切</th><td>${t.dueAt?`${when(t.dueAt)}${pending(t)?` <span class="deadline ${overdue(t)?'overdue':''}">（${remaining(t)}）</span>`:''}`:'締切未確認'}</td></tr>${key?`<tr><th>最終確認</th><td>${when(t.checkedAt)}</td></tr>`:''}${t.action?`<tr><th>次の対応</th><td>${esc(t.action)}</td></tr>`:''}</table>`;
if(!key)body+=`<h3>課題情報</h3><div class="field"><label for="edit-title">課題名</label><input class="form-control" id="edit-title" value="${esc(t.title)}"></div><div class="field"><label for="edit-course">授業</label><select class="form-control" id="edit-course">${courses.map((c,i)=>`<option value="${i}"${i===t.course?' selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="field"><label for="edit-type">種類</label><select class="form-control" id="edit-type">${[...new Set([...taskTypes,t.type||'課題'])].map(v=>`<option${v===(t.type||'課題')?' selected':''}>${esc(v)}</option>`).join('')}</select></div><div class="field"><label for="edit-due">締切</label><input class="form-control" id="edit-due" type="datetime-local" value="${localInput(t.dueAt)}"></div>`;
body+=`<h3>設問</h3>${t.description?`<p class="question">${esc(t.description)}</p>`:`<p class="muted">${key?'設問はまだ取得されていません。同期すると表示されます。':'設問は登録されていません。'}</p>`}<h3><label for="answer">回答・下書き</label></h3><textarea class="form-control" id="answer">${esc(t.answer)}</textarea>`;
if(key){body+=`<h3><label for="supplement">本人の経験・補足</label></h3><textarea class="form-control" id="supplement">${esc(t.supplement||'')}</textarea><div class="actions"><button class="btn" id="save">保存</button><button class="btn btn-primary" id="generate">${quiz?'回答開始・自動回答':'課題を生成'}</button><button class="btn" id="download">ダウンロード</button>${!['done','code','unknown','answered'].includes(t.status)&&!quiz?'<button class="btn" id="submit">manaboに提出</button>':''}${t.url?`<a class="btn" href="${esc(t.url)}" target="_blank" rel="noopener">manaboで開く</a>`:''}${(['code','answered'].includes(t.status)||(quiz&&t.generation))?'<a class="btn" href="http://127.0.0.1:8766/browser" target="_blank" rel="noopener">待機中のブラウザ</a>':''}</div><h3>根拠</h3><p class="evidence">${esc(t.generation?.answers?.map(a=>a.evidence).join('\n\n')||'未生成')}</p>`}
else body+=`<div class="actions"><button class="btn btn-primary" id="save">保存</button><button class="btn" id="download">ダウンロード</button><button class="btn" id="togglestatus">${pending(t)?'提出済みにする':'未提出に戻す'}</button><button class="btn" id="deletetask">削除</button></div><p class="muted" style="margin-top:10px">自動回答・課題生成はmanabo連携時に利用できます。</p>`;
openDrawer(t.title,body);const val=i=>document.getElementById(i).value;
document.getElementById('download').onclick=()=>{const url=URL.createObjectURL(new Blob([val('answer')],{type:'text/markdown'})),a=document.createElement('a');a.href=url;a.download=`${t.round?'第'+t.round+'回_':''}${t.title}_下書き.md`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
if(key){const save=()=>job('supplement',id,{text:val('supplement'),answer:val('answer')});document.getElementById('save').onclick=save;document.getElementById('generate').onclick=async()=>{await save();await job('generate',id)};const sub=document.getElementById('submit');if(sub)sub.onclick=async()=>{if(await ask('この課題をmanaboに提出しますか？提出後は取り消せません。','提出する'))job('submit',id)};return}
document.getElementById('save').onclick=()=>{const title=val('edit-title').trim();if(!title){toast('課題名を入力してください');return}const due=val('edit-due');Object.assign(t,{title,course:+val('edit-course'),type:val('edit-type'),dueAt:due?new Date(due).toISOString():null,answer:val('answer')});savePersonal();render();detail(id);toast('保存しました')};
document.getElementById('togglestatus').onclick=()=>{if(pending(t)){t.status='done';t.submittedAt=new Date().toISOString();toast('提出済みにしました')}else{t.status=t.answer?'draft':'ready';delete t.submittedAt;toast('未提出に戻しました')}savePersonal();render();detail(id)};
document.getElementById('deletetask').onclick=async()=>{if(!await ask(`「${t.title}」を削除しますか？元に戻せません。`,'削除',true))return;state.tasks=state.tasks.filter(x=>x.id!==id);savePersonal();close();render();toast('課題を削除しました')}}
document.getElementById('searchicon').innerHTML=ic('search');document.getElementById('search').oninput=e=>{query=e.target.value;render()};document.getElementById('overlay').onclick=e=>{if(e.target.id==='overlay')close()};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(dialogDone)dialogDone(false);else close();return}if(e.key!=='Tab')return;const box=dialogDone?document.getElementById('dialog'):document.getElementById('overlay').classList.contains('open')?document.getElementById('drawer'):null;if(!box)return;const es=[...box.querySelectorAll('button:not(:disabled),a[href],input:not(.file-input),select,textarea,summary')],first=es[0],last=es.at(-1);if(!first)return;if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}});
const fragment=new URLSearchParams(location.hash.slice(1));if(fragment.has('connect')){courses=ownerCourses;state=emptyState();key=fragment.get('connect');history.replaceState(null,'',location.pathname);localStorage.setItem('coursecue-owner',key)}render();load();setInterval(load,15000);
